(209137, '_transient_ctf__NIck_Alvarez673', '[{\"user\":{\"name\":\"Nick Alvarez\",\"description\":\"Managing Director & National Practice Leader, @alvarezmarsal Private Equity Performance Improvement; Loves good wine, golf & @SoulCycle; Posts are my own views.\",\"statuses_count\":1464,\"followers_count\":347,\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Both wine and conversation always flow when I\'m with this group. Cheers to @AlvarezMarsal! @PaulAversano #LoveWhatYouDo #LoveWhoYouDoItWith #MotivationMonday \",\"id_str\":\"1214227896799256578\",\"created_at\":\"Mon Jan 06 16:51:04 +0000 2020\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/ENnN1dpXkAIH-qY.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"#NewYorkCity is brimming with art every year; 2020 will be no exception. Can\'t wait to check these out! @BigSevenTravel: https:\\/\\/t.co\\/R4M63JUeQW #FunFriday #NYC #MoMA #NYC @SazzyClay\",\"id_str\":\"1213147512284024832\",\"created_at\":\"Fri Jan 03 17:18:00 +0000 2020\",\"retweet_count\":0,\"favorite_count\":6,\"entities\":{\"urls\":[{\"expanded_url\":\"http:\\/\\/bit.ly\\/2PMzL16\"}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"#TBT to showing some pride for my home country with some delicious vino! \\ud83c\\uddf5\\ud83c\\udded #WineLover #Philippines \",\"id_str\":\"1212768774761467906\",\"created_at\":\"Thu Jan 02 16:13:02 +0000 2020\",\"retweet_count\":0,\"favorite_count\":7,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/ENSexZVXsAMDWKG.jpg\",\"type\":\"photo\",\"sizes\":{\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}}]', 'no'),
