(209141, '_transient_ctf__Ernie_R_Perez3', '[{\"user\":{\"name\":\"Ernie Perez\",\"description\":\"Global Practice Leader, @alvarezmarsal Taxand;Transaction Advisory Tax, Domestic\\/Cross-Border Acquisitions, Divestitures, Reorgs @universityofga @miamilawschool\",\"statuses_count\":1887,\"followers_count\":240,\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/950416735265574912\\/dWfvYVGb_normal.jpg\",\"utc_offset\":null},\"text\":\"There\'s a price for everything, but the price for success is absolutely worth it. #FrankLloydWright #QOTD \",\"id_str\":\"1213233599887093760\",\"created_at\":\"Fri Jan 03 23:00:05 +0000 2020\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/ENZFh0TXkAAsGUD.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/950416735265574912\\/dWfvYVGb_normal.jpg\",\"utc_offset\":null},\"text\":\"A shout out to @alvarezmarsal #Taxand\\u2019s newly promoted Managing Director, @kennydettman! Congrats on your promotion! #Promotions #TaxAdvisory #FinancialServices \",\"id_str\":\"1213199930094960640\",\"created_at\":\"Fri Jan 03 20:46:18 +0000 2020\",\"retweet_count\":0,\"favorite_count\":7,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/ENYm507WsAE_CWk.jpg\",\"type\":\"photo\",\"sizes\":{\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Ernie Perez\",\"screen_name\":\"Ernie_R_Perez\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/950416735265574912\\/dWfvYVGb_normal.jpg\",\"utc_offset\":null},\"text\":\"At @AlvarezMarsal #Taxand, the growth &amp; development of our people are of high priority, &amp; thanks to the hard work of our exceptional leaders like Managing Director @AlbertLiguori, we see our team growing in size, talent, and value. #LikeWhatYouDo #LikeWhoYouDoItWith #TaxServices \",\"id_str\":\"1213125877569114114\",\"created_at\":\"Fri Jan 03 15:52:02 +0000 2020\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/ENXjjjFW4AAOKKR.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"}}}]}}]', 'no'),
